def solve(**kwargs):
    n = kwargs['n']
    m = kwargs['m']
    matrix = kwargs['matrix']
    if n == 0:
        return {'job_sequence': []}
    def makespan(seq, matrix):
        N = len(seq)
        M = len(matrix[0])
        C = [[0] * M for _ in range(N + 1)]
        for i in range(1, N + 1):
            job = seq[i - 1]
            for j in range(M):
                if j == 0:
                    C[i][j] = C[i - 1][j] + matrix[job][j]
                else:
                    C[i][j] = max(C[i - 1][j], C[i][j - 1]) + matrix[job][j]
        return C[N][M - 1]
    if n == 1:
        return {'job_sequence': [1]}
    totals = [sum(row) for row in matrix]
    jobs = sorted(range(n), key=lambda x: totals[x], reverse=True)
    best_makes = float('inf')
    best_seq = None
    for perm in [[jobs[0], jobs[1]], [jobs[1], jobs[0]]]:
        seq = perm
        mk = makespan(seq, matrix)
        if mk < best_makes:
            best_makes = mk
            best_seq = seq[:]
    current_seq = best_seq[:]
    for k in range(2, n):
        job = jobs[k]
        best_makes = float('inf')
        best_pos = 0
        for pos in range(k + 1):
            new_seq = current_seq[:pos] + [job] + current_seq[pos:]
            mk = makespan(new_seq, matrix)
            if mk < best_makes:
                best_makes = mk
                best_pos = pos
        current_seq = current_seq[:best_pos] + [job] + current_seq[best_pos:]
    seq1 = [x + 1 for x in current_seq]
    return {'job_sequence': seq1}
